        if operation == "count":
            result = len(data)

        elif operation in {"sort", "max", "min"}:
            if not target_field:
                return enrich_tool_result(
                    {
                        "status": "no_valid_result",
                        "operation": operation,
                        "result": f"Aggregation operation={operation!r} requires target_field.",
                    },
