                "type": "string",
                "description": "Time range constraint (format: 'HH:MM:SS-HH:MM:SS' or 'SS-SS')",
                "default": None
            },
            "top_k": {
                "type": "integer",
                "description": "Number of results to return",
                "default": 5
            }
        },
        "required": ["query"]
    }

